// Public metadata snapshot. Original descriptions and applications stay at source.
let publicDataReady=false,visiblePublicJobs=24;
function uniquePublicCompaniesVPJ(){const map=new Map();for(const j of jobs.filter(j=>j.sourceUrl)){const key=j.companySlug||j.company;if(!map.has(key))map.set(key,j)}return [...map.values()]}
const demoDetailVPJ=detail,demoApplyVPJ=apply,localCardVPJ=card;
function avatarVPJ(j){const url=j.logoUrl||j.posterUrl;const initials=(j.company||'VPJ').replace(/Công ty|TNHH|Cổ phần|Nhà máy/gi,'').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'VPJ';return `<div class="company-logo"><span class="avatar-fallback">${esc(initials)}</span>${url?`<img src="${esc(url)}" alt="Ảnh đại diện ${esc(j.company)}" loading="lazy" referrerpolicy="no-referrer" style="position:absolute;inset:0" onerror="this.remove()">`:''}</div>`}
function deadlineExpiredVPJ(j){if(!j.deadline)return false;const [d,m,y]=j.deadline.split('/');return `${y}-${m}-${d}`<new Date().toISOString().slice(0,10)}
card=function(j){if(!j.sourceUrl)return localCardVPJ(j);return `<article class="job"><button class="save ${saved.includes(j.id)?'saved':''}" data-save="${j.id}" aria-label="${saved.includes(j.id)?'Bỏ lưu':'Lưu'} ${esc(j.title)}" aria-pressed="${saved.includes(j.id)}">${saved.includes(j.id)?'♥':'♡'}</button><div class="job-top">${avatarVPJ(j)}<div class="company-name">${esc(j.company)}<br><span class="verified">Vĩnh Phúc Work ↗</span></div></div><h3><button class="detail-button" style="font-size:inherit;text-align:left;color:var(--dark);line-height:inherit" data-detail="${j.id}">${esc(j.title)}</button></h3><div class="salary">${esc(j.salaryText)}</div><div class="place">⌖ ${esc(j.address)}</div><div class="tags"><span class="tag">${esc(j.category)}</span>${j.deadline?`<span class="tag">${deadlineExpiredVPJ(j)?'Đã qua hạn':'Hạn'} ${esc(j.deadline)}</span>`:'<span class="tag">Kiểm tra hạn tại nguồn</span>'}</div><div class="job-bottom"><span>Đăng ${esc(j.published.split('-').reverse().join('/'))}</span><button class="detail-button" data-detail="${j.id}">Xem tin ↗</button></div><label class="compare-toggle"><input type="checkbox" data-compare="${j.id}" ${selectedCompare.includes(j.id)?'checked':''}> So sánh tin</label></article>`};
function publicFilteredVPJ(){const cats=$$('input[name=category]:checked').map(x=>x.value),types=$$('input[name=type]:checked').map(x=>x.value),q=norm($('#query').value.trim()),loc=$('#location').value,min=+$('#salaryFilter').value,exp=$('#experienceFilter').value,period=$('#periodFilter').value;return jobs.filter(j=>j.status!=='paused'&&(!q||norm(j.title+' '+j.company+' '+j.category+' '+j.address+' '+(j.positions||[]).join(' ')+' '+(j.skills||[]).join(' ')).includes(q))&&(!loc||j.location===loc)&&(!cats.length||cats.includes(j.category))&&(!types.length||types.includes(j.type))&&j.min>=min&&(!exp||((j.experienceFlags||[]).includes(exp)||(!j.sourceUrl&&(exp==='none'?j.exp==='Không cần kinh nghiệm':j.exp!=='Không cần kinh nghiệm'))))&&(!j.sourceUrl||period==='all'||j.days<=+period)).sort($('#sort').value==='salary'?(a,b)=>b.max-a.max:(a,b)=>a.days-b.days)}
render=function(){const list=publicFilteredVPJ();$('#resultCount').innerHTML=`<b>${list.length.toLocaleString('vi-VN')}</b> tin phù hợp`;$('#jobCards').innerHTML=list.length?list.slice(0,visiblePublicJobs).map(card).join(''):'<div class="empty">Chưa có tin phù hợp.<br>Thử chọn “Toàn bộ kho tin” hoặc đổi bộ lọc.</div>';$('#moreBtn').style.display=list.length>visiblePublicJobs?'inline-flex':'none';$('#moreBtn').textContent=`Xem thêm 24 tin (${Math.min(visiblePublicJobs,list.length)}/${list.length}) ↓`;$('#savedCards').innerHTML=jobs.filter(j=>saved.includes(j.id)).map(card).join('')||'<div class="empty">Nhấn ♡ trên tin tuyển dụng để lưu tại đây.</div>';$('#loginBtn').textContent=user?'◎ '+user.name:'Đăng nhập';$('#compareCount').textContent=selectedCompare.length;renderEmployer();renderApplications()};
$('#moreBtn').onclick=()=>{visiblePublicJobs+=24;render()};$('#periodFilter').onchange=()=>{visiblePublicJobs=24;render()};const resetBeforePublicVPJ=reset;reset=function(){visiblePublicJobs=24;$('#periodFilter').value='60';resetBeforePublicVPJ()};
detail=function(id){const j=jobs.find(x=>x.id===id);if(!j?.sourceUrl)return demoDetailVPJ(id);openModal(`<div class="job-top">${avatarVPJ(j)}<div><div class="eyebrow">VĨNH PHÚC WORK · TIN CÔNG KHAI</div><h2>${esc(j.title)}</h2><p>${esc(j.company)}</p></div></div><div class="job-metadata"><b>Địa điểm:</b> ${esc(j.address)}<br><b>Lương:</b> ${esc(j.salaryText)}<br><b>Ngày đăng:</b> ${esc(j.published.split('-').reverse().join('/'))}<br><b>Hạn tuyển:</b> ${j.deadline?esc(j.deadline)+(deadlineExpiredVPJ(j)?' · Đã qua hạn':''):'Chưa có trong dữ liệu nhập; kiểm tra tin gốc.'}</div><p>Mở tin gốc để đọc các vị trí, yêu cầu, quyền lợi và liên hệ tuyển dụng. VPJ hiển thị thông tin tra cứu từ nguồn công khai.</p><div class="actions"><a class="btn primary" href="${esc(j.sourceUrl)}" target="_blank" rel="noopener noreferrer">Đọc đầy đủ / Ứng tuyển tại nguồn ↗</a><button class="btn" id="saveSourceJob">${saved.includes(j.id)?'Bỏ lưu':'♡ Lưu tin'}</button></div>${j.posterUrl?`<img class="source-preview" src="${esc(j.posterUrl)}" loading="lazy" alt="Hình tuyển dụng tại nguồn" referrerpolicy="no-referrer">`:''}<p class="page-note">Bản dữ liệu nhập ngày 11/10/2026. Trạng thái tuyển dụng có thể đã thay đổi; xem thông tin mới nhất tại nguồn.</p>`,true);$('#saveSourceJob').onclick=()=>{toggleSave(j.id);detail(j.id)}};
apply=function(id){const j=jobs.find(x=>x.id===id);if(j?.sourceUrl)return detail(id);return demoApplyVPJ(id)};
function renderPublicCompaniesVPJ(){companies.splice(0,companies.length,...uniquePublicCompaniesVPJ());const current=uniquePublicCompaniesVPJ();$('#companyCards').innerHTML=current.slice(0,120).map(j=>`<article class="job"><div class="job-top">${avatarVPJ(j)}<div><b>${esc(j.company)}</b><p class="mini-info">${esc(j.location)} · Thông tin từ nguồn</p></div></div><div class="job-bottom"><span>${jobs.filter(x=>x.companySlug&&x.companySlug===j.companySlug).length||1} tin trong kho</span><button class="detail-button" data-realcompany="${esc(j.company)}">Xem tin ↗</button></div></article>`).join('');$('#employerShowcase').innerHTML=current.filter(j=>j.logoUrl).slice(0,6).map(j=>`<button class="employer-tile" data-realcompany="${esc(j.company)}">${avatarVPJ(j)}<h3>${esc(j.company)}</h3><small>${esc(j.location)}</small></button>`).join('');const subtitle=$('#companiesView .page-note');if(subtitle)subtitle.textContent=`${current.length.toLocaleString('vi-VN')} doanh nghiệp/nhóm tin trong kho. Hiển thị 120 đơn vị; tìm tên công ty trên trang Tìm việc.`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-realcompany]');if(b){reset();$('#periodFilter').value='all';$('#query').value=b.dataset.realcompany;view('jobs')}});
function publicHomeVPJ(count){$('#featuredGrid').innerHTML=jobs.filter(j=>j.sourceUrl).slice(0,3).map(j=>`<article class="spotlight-job"><div class="spotlight-head">${avatarVPJ(j)}<span class="hot-pill">TIN TỪ NGUỒN</span></div><h3><button data-detail="${j.id}">${esc(j.title)}</button></h3><p>${esc(j.company)}</p><div class="salary">${esc(j.salaryText)}</div><div class="spotlight-meta"><span>⌖ ${esc(j.location)}</span><span>Đăng ${esc(j.published.split('-').reverse().join('/'))}</span></div></article>`).join('');$$('#categoryGrid .category-tile').forEach(e=>{const small=e.querySelector('small');if(small)small.textContent=jobs.filter(j=>j.sourceUrl&&j.category===e.dataset.categorypick).length.toLocaleString('vi-VN')+' tin trong kho'});$$('.stats-inner .stat').forEach((e,i)=>{if(i===0)e.innerHTML=`<strong>${count.toLocaleString('vi-VN')}</strong><span>Tin công khai trong kho</span>`;if(i===1)e.innerHTML=`<strong>${companies.length.toLocaleString('vi-VN')}</strong><span>Doanh nghiệp / nhóm tin</span>`});$('#dataBanner').innerHTML=`<div><strong>${count.toLocaleString('vi-VN')} tin công khai từ Vĩnh Phúc Work</strong><span>Nhập ngày 11/10/2026 · Gồm tin mới và kho tin cũ · Mô tả đầy đủ, hạn tuyển và liên hệ tại nguồn.</span></div><a href="https://vinhphuc.work/tin-tuyen-dung" target="_blank" rel="noopener noreferrer">Vĩnh Phúc Work ↗</a>`}
async function loadPublicJobsVPJ(){try{const response=await fetch('data/jobs.json?v=6');if(!response.ok)throw Error('HTTP '+response.status);const imported=await response.json();if(!Array.isArray(imported)||!imported.length)throw Error('Empty data');jobs.splice(0,jobs.length,...imported,...ownedJobsVPJ);publicDataReady=true;jobs.forEach(j=>{if(j.companySlug&&!j.companyUrl)j.companyUrl='https://vinhphuc.work/cong-ty/'+encodeURIComponent(j.companySlug);if(j.published)j.days=Math.max(0,Math.floor((Date.now()-Date.parse(j.published+'T00:00:00+07:00'))/86400000))});renderPublicCompaniesVPJ();publicHomeVPJ(imported.length);render();if(typeof upgradePublicExperienceVPJ==='function')upgradePublicExperienceVPJ()}catch(e){jobs.splice(0,jobs.length,...ownedJobsVPJ);$('#dataBanner').innerHTML='<div><strong>Chưa tải được dữ liệu</strong><span>Hãy tải lại trang hoặc mở Vĩnh Phúc Work để tra cứu.</span></div><a href="https://vinhphuc.work/tin-tuyen-dung" target="_blank" rel="noopener noreferrer">Mở nguồn ↗</a>';$('#featuredGrid').innerHTML='';$('#employerShowcase').innerHTML='';render();console.error('Public data:',e.message)}}
loadPublicJobsVPJ();
